// Seeds the first real, fully-authored Roadmaps catalog entry (ML Engineer)
// end to end - roadmap doc, modules, topics - via the Admin SDK, matching
// the exact field shapes lib/roadmaps.js's client-side API writes. Run once
// to validate the data model + rules against a real build (see the
// project's Roadmaps build plan, phase 2) before any admin panel exists.
//
// Uses admin.firestore() directly (not the client lib/roadmaps.js
// functions) because this is a Node script running under firebase-admin,
// a different SDK from the client "firebase/firestore" those functions
// import - the same reason every other scripts/seed-*.mjs does the same.
//
// Re-running is safe: matches by the roadmap's `slug` field and updates in
// place (merge:true) rather than creating a duplicate.
import admin from "firebase-admin";
import { readFileSync } from "fs";
import { fileURLToPath } from "url";
import path from "path";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const serviceAccount = JSON.parse(readFileSync(path.join(__dirname, "service-account.json"), "utf8"));
admin.initializeApp({ credential: admin.credential.cert(serviceAccount) });
const db = admin.firestore();
const FV = admin.firestore.FieldValue;

const AUDIENCES = ["public", "legacy"];

// `modules` is deliberately NOT part of the roadmap document - it's a
// subcollection (see upsertModules). Only used here to derive the
// denormalized counts; excluded from the actual write via destructuring, or
// the full tree (every topic's full content) would get embedded onto the
// roadmap doc itself, both wrong for the schema and a real risk of blowing
// past Firestore's 1MiB document cap.
async function upsertRoadmap({ modules, ...roadmapFields }) {
  const existing = await db.collection("roadmaps").where("slug", "==", roadmapFields.slug).limit(1).get();
  const ref = existing.empty ? db.collection("roadmaps").doc() : existing.docs[0].ref;
  await ref.set({
    ...roadmapFields,
    audiences: AUDIENCES,
    authoringStatus: "authored",
    moduleCount: modules.length,
    topicCount: modules.reduce((n, m) => n + m.topics.length, 0),
    levelTopicCounts: modules.reduce((acc, m) => {
      acc[m.level] = (acc[m.level] || 0) + m.topics.length;
      return acc;
    }, { beginner: 0, intermediate: 0, advanced: 0 }),
    previousVersions: [],
    updatedAt: FV.serverTimestamp(),
  }, { merge: true });
  return ref;
}

async function upsertModules(roadmapRef, modulesData) {
  for (const m of modulesData) {
    const { topics, ...moduleFields } = m;
    const existing = await roadmapRef.collection("modules").where("importKey", "==", m.importKey).limit(1).get();
    const moduleRef = existing.empty ? roadmapRef.collection("modules").doc() : existing.docs[0].ref;
    await moduleRef.set({
      ...moduleFields,
      audiences: AUDIENCES,
      resources: moduleFields.resources || [],
      projects: moduleFields.projects || [],
      milestones: moduleFields.milestones || [],
      topicCount: topics.length,
      previousVersions: [],
      updatedAt: FV.serverTimestamp(),
    }, { merge: true });

    for (const t of topics) {
      const existingTopic = await moduleRef.collection("topics").where("importKey", "==", t.importKey).limit(1).get();
      const topicRef = existingTopic.empty ? moduleRef.collection("topics").doc() : existingTopic.docs[0].ref;
      await topicRef.set({
        ...t,
        audiences: AUDIENCES,
        resources: t.resources || [],
        projects: t.projects || [],
        mcqs: t.mcqs || [],
        keyConcepts: t.keyConcepts || [],
        tools: t.tools || [],
        practiceExercises: t.practiceExercises || [],
        commonMistakes: t.commonMistakes || [],
        realWorldApplications: t.realWorldApplications || [],
        prerequisiteTopicIds: [],
        prerequisiteRoadmapIds: [],
        languageVariants: {},
        previousVersions: [],
        updatedAt: FV.serverTimestamp(),
      }, { merge: true });
    }
    console.log(`  module "${m.title}" (${m.level}) - ${topics.length} topics`);
  }
}

