const ALL_ROADMAPS = [ML_ENGINEER, AI_ENGINEER, CYBERSECURITY_ENGINEER, VLSI_ENGINEER];

async function main() {
  for (const roadmap of ALL_ROADMAPS) {
    console.log(`\nSeeding roadmap: ${roadmap.title}`);
    const ref = await upsertRoadmap(roadmap);
    console.log(`roadmaps/${ref.id}`);
    await upsertModules(ref, roadmap.modules);
  }
  console.log("\nDone.");
}

main().then(() => process.exit(0)).catch((e) => { console.error(e); process.exit(1); });
